// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MultiplicatorX3} from "../src/MultiplicatorX3.sol";

contract InvMutTest is Test {
    MultiplicatorX3 c;

    function setUp() public { c = new MultiplicatorX3(); }

    function testFuzz_property(uint128 ethAmount, bool makeRevert) public {
        uint256 amount = bound(uint256(ethAmount), 0, 1 ether);

        ReverterHelper helper = new ReverterHelper();

        address owner = address(this);
        vm.deal(owner, amount);

        bytes memory data = makeRevert ? abi.encodePacked(uint8(1)) : abi.encodePacked(uint8(0));

        bool ok;
        vm.prank(owner);
        try c.Command(address(helper), data) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(ok);
    }
}

contract ReverterHelper {
    fallback() external payable {
        if (msg.data.length > 0 && msg.data[0] == 0x01) {
            revert("helper revert");
        }
    }
}
